func (os PurchaseSlice) CreatedByMember(mods ...bob.Mod[*dialect.SelectQuery]) MembersQuery {
	pkCreatedBy := make(pgtypes.Array[uuid.UUID], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenCreatedBy := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenCreatedBy[o.CreatedBy]; ok {
			continue
		}
		seenCreatedBy[o.CreatedBy] = struct{}{}
		pkCreatedBy = append(pkCreatedBy, o.CreatedBy)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkCreatedBy), "uuid[]"))

	return Members.Query(append(mods,
		sm.Where(Members.Columns.ID.EQ(PKArgExpr)),
	)...)
}

