// NULL-tolerant scan buffer for purchaseScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type purchasePreloadBuf struct {
	ID                    sql.Null[uuid.UUID]
	HouseholdID           sql.Null[uuid.UUID]
	OccurredAt            sql.Null[time.Time]
	Merchant              sql.Null[string]
	PaymentAccountID      sql.Null[uuid.UUID]
	Status                sql.Null[string]
	Revision              sql.Null[int64]
	FieldRevisions        sql.Null[types.JSON[json.RawMessage]]
	AllocationRuleVersion sql.Null[int64]
	CreatedBy             sql.Null[uuid.UUID]
	CreatedAt             sql.Null[time.Time]
	UpdatedAt             sql.Null[time.Time]
}

// purchaseScanMapperNullable maps the preloaded purchase
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func purchaseScanMapperNullable(prefix string) scan.Mapper[*Purchase] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Purchase, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *purchasePreloadBuf) any
		}
		targets := make([]target, 0, 12)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.HouseholdID }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.OccurredAt }})
			case "merchant":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.Merchant }})
			case "payment_account_id":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.PaymentAccountID }})
			case "status":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.Status }})
			case "revision":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.Revision }})
			case "field_revisions":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.FieldRevisions }})
			case "allocation_rule_version":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.AllocationRuleVersion }})
			case "created_by":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.CreatedBy }})
			case "created_at":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *purchasePreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(purchasePreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Purchase, error) {
				buf := link.(*purchasePreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.OccurredAt.Valid) &&
					!(buf.Merchant.Valid) &&
					!(buf.PaymentAccountID.Valid) &&
					!(buf.Status.Valid) &&
					!(buf.Revision.Valid) &&
					!(buf.FieldRevisions.Valid) &&
					!(buf.AllocationRuleVersion.Valid) &&
					!(buf.CreatedBy.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.UpdatedAt.Valid) {
					return nil, nil
				}

				o := new(Purchase)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.OccurredAt.Valid {
					o.OccurredAt = buf.OccurredAt.V
				}
				if buf.Merchant.Valid {
					o.Merchant = buf.Merchant.V
				}
				o.PaymentAccountID = buf.PaymentAccountID
				if buf.Status.Valid {
					o.Status = buf.Status.V
				}
				if buf.Revision.Valid {
					o.Revision = buf.Revision.V
				}
				if buf.FieldRevisions.Valid {
					o.FieldRevisions = buf.FieldRevisions.V
				}
				if buf.AllocationRuleVersion.Valid {
					o.AllocationRuleVersion = buf.AllocationRuleVersion.V
				}
				if buf.CreatedBy.Valid {
					o.CreatedBy = buf.CreatedBy.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				if buf.UpdatedAt.Valid {
					o.UpdatedAt = buf.UpdatedAt.V
				}
				return o, nil
			}
	}
}

func (o *Purchase) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Corrections":
		rels, ok := retrieved.(CorrectionSlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.Corrections = rels
		o.R.Loaded.Corrections = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "DocumentConfirmations":
		rels, ok := retrieved.(DocumentConfirmationSlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.DocumentConfirmations = rels
		o.R.Loaded.DocumentConfirmations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "EvidenceLinks":
		rels, ok := retrieved.(EvidenceLinkSlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.EvidenceLinks = rels
		o.R.Loaded.EvidenceLinks = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "LedgerEntries":
		rels, ok := retrieved.(LedgerEntrySlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.LedgerEntries = rels
		o.R.Loaded.LedgerEntries = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "PurchaseItems":
		rels, ok := retrieved.(PurchaseItemSlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.PurchaseItems = rels
		o.R.Loaded.PurchaseItems = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "PurchasePayments":
		rels, ok := retrieved.(PurchasePaymentSlice)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.PurchasePayments = rels
		o.R.Loaded.PurchasePayments = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Purchase = o
				rel.R.Loaded.Purchase = true
			}
		}
		return nil
	case "CreatedByMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.CreatedByMember = rel
		o.R.Loaded.CreatedByMember = true

		if rel != nil {
			rel.R.CreatedByPurchases = PurchaseSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.Purchases = PurchaseSlice{o}
		}
		return nil
	case "Account":
		rel, ok := retrieved.(*Account)
		if !ok {
			return fmt.Errorf("purchase cannot load %T as %q", retrieved, name)
		}

		o.R.Account = rel
		o.R.Loaded.Account = true

		if rel != nil {
			rel.R.Purchases = PurchaseSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("purchase has no relationship %q", name)
	}
}

type purchasePreloader struct {
	CreatedByMember func(...psql.PreloadOption) psql.Preloader
	Household       func(...psql.PreloadOption) psql.Preloader
	Account         func(...psql.PreloadOption) psql.Preloader
}

func buildPurchasePreloader() purchasePreloader {
	return purchasePreloader{
		CreatedByMember: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "CreatedByMember",
				Sides: []psql.PreloadSide{
					{
						From:        Purchases,
						To:          Members,
						FromColumns: []string{"created_by"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        Purchases,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
		Account: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Account, AccountSlice](psql.PreloadRel{
				Name: "Account",
				Sides: []psql.PreloadSide{
					{
						From:        Purchases,
						To:          Accounts,
						FromColumns: []string{"household_id", "payment_account_id"},
						ToColumns:   []string{"household_id", "id"},
					},
				},
			}, Accounts.Columns.Names(), accountScanMapperNullable, opts...)
		},
	}
}

