type purchaseCountThenLoader[Q orm.Loadable] struct {
	Corrections           func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	DocumentConfirmations func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	EvidenceLinks         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	LedgerEntries         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PurchaseItems         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PurchasePayments      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildPurchaseCountThenLoader[Q orm.Loadable]() purchaseCountThenLoader[Q] {
	type CorrectionsCountInterface interface {
		LoadCountCorrections(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type DocumentConfirmationsCountInterface interface {
		LoadCountDocumentConfirmations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type EvidenceLinksCountInterface interface {
		LoadCountEvidenceLinks(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type LedgerEntriesCountInterface interface {
		LoadCountLedgerEntries(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PurchaseItemsCountInterface interface {
		LoadCountPurchaseItems(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PurchasePaymentsCountInterface interface {
		LoadCountPurchasePayments(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return purchaseCountThenLoader[Q]{
		Corrections: countThenLoadBuilder[Q](
			"Corrections",
			func(ctx context.Context, exec bob.Executor, retrieved CorrectionsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountCorrections(ctx, exec, mods...)
			},
		),
		DocumentConfirmations: countThenLoadBuilder[Q](
			"DocumentConfirmations",
			func(ctx context.Context, exec bob.Executor, retrieved DocumentConfirmationsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountDocumentConfirmations(ctx, exec, mods...)
			},
		),
		EvidenceLinks: countThenLoadBuilder[Q](
			"EvidenceLinks",
			func(ctx context.Context, exec bob.Executor, retrieved EvidenceLinksCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountEvidenceLinks(ctx, exec, mods...)
			},
		),
		LedgerEntries: countThenLoadBuilder[Q](
			"LedgerEntries",
			func(ctx context.Context, exec bob.Executor, retrieved LedgerEntriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountLedgerEntries(ctx, exec, mods...)
			},
		),
		PurchaseItems: countThenLoadBuilder[Q](
			"PurchaseItems",
			func(ctx context.Context, exec bob.Executor, retrieved PurchaseItemsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountPurchaseItems(ctx, exec, mods...)
			},
		),
		PurchasePayments: countThenLoadBuilder[Q](
			"PurchasePayments",
			func(ctx context.Context, exec bob.Executor, retrieved PurchasePaymentsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountPurchasePayments(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountCorrections loads the count of Corrections into the C struct
func (o *Purchase) LoadCountCorrections(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Corrections(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Corrections = &count
	return nil
}

// LoadCountCorrections loads the count of Corrections for a slice in a single batch query
func (os PurchaseSlice) LoadCountCorrections(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkID = append(pkID, o.ID)
	}

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		HouseholdID uuid.UUID

		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Corrections.Columns.HouseholdID.As("household_id"),
			Corrections.Columns.PurchaseID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Corrections.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(
				psql.Quote("bob_rel_keys_src", "HouseholdID"),
				psql.Quote("bob_rel_keys_src", "PurchaseID"),
			),
			sm.From(psql.F("unnest",
				psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"),
				psql.Cast(psql.Arg(pkID), "uuid[]"),
			)).As("bob_rel_keys_src", "HouseholdID", "PurchaseID"),
		)).As("bob_rel_keys").On(
			Corrections.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")),
			Corrections.Columns.PurchaseID.EQ(psql.Quote("bob_rel_keys", "PurchaseID")),
		),
		// GROUP BY fk columns
		sm.GroupBy(Corrections.Columns.HouseholdID),
		sm.GroupBy(Corrections.Columns.PurchaseID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Composite FK: use a key struct
	type countKey struct {
		HouseholdID uuid.UUID

		ID uuid.UUID
	}
	countMap := make(map[countKey]int64, len(results))
	for _, r := range results {
		countMap[countKey{
			HouseholdID: r.HouseholdID,

			ID: r.ID,
		}] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[countKey{
			HouseholdID: o.HouseholdID,

			ID: o.ID,
		}]
		o.C.Corrections = &count
	}

	return nil
}

