type purchaseJoins[Q dialect.Joinable] struct {
	typ                   string
	Corrections           modAs[Q, correctionColumns]
	DocumentConfirmations modAs[Q, documentConfirmationColumns]
	EvidenceLinks         modAs[Q, evidenceLinkColumns]
	LedgerEntries         modAs[Q, ledgerEntryColumns]
	PurchaseItems         modAs[Q, purchaseItemColumns]
	PurchasePayments      modAs[Q, purchasePaymentColumns]
	CreatedByMember       modAs[Q, memberColumns]
	Household             modAs[Q, householdColumns]
	Account               modAs[Q, accountColumns]
}

func (j purchaseJoins[Q]) aliasedAs(alias string) purchaseJoins[Q] {
	return buildPurchaseJoins[Q](buildPurchaseColumns(alias), j.typ)
}

func buildPurchaseJoins[Q dialect.Joinable](cols purchaseColumns, typ string) purchaseJoins[Q] {
	return purchaseJoins[Q]{
		typ: typ,
		Corrections: modAs[Q, correctionColumns]{
			c: Corrections.Columns,
			f: func(to correctionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Corrections.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		DocumentConfirmations: modAs[Q, documentConfirmationColumns]{
			c: DocumentConfirmations.Columns,
			f: func(to documentConfirmationColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, DocumentConfirmations.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		EvidenceLinks: modAs[Q, evidenceLinkColumns]{
			c: EvidenceLinks.Columns,
			f: func(to evidenceLinkColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, EvidenceLinks.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		LedgerEntries: modAs[Q, ledgerEntryColumns]{
			c: LedgerEntries.Columns,
			f: func(to ledgerEntryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, LedgerEntries.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.SourcePurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PurchaseItems: modAs[Q, purchaseItemColumns]{
			c: PurchaseItems.Columns,
			f: func(to purchaseItemColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchaseItems.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PurchasePayments: modAs[Q, purchasePaymentColumns]{
			c: PurchasePayments.Columns,
			f: func(to purchasePaymentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchasePayments.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		CreatedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedBy),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PaymentAccountID),
					))
				}

				return mods
			},
		},
	}
}
